            raf = 0
            if (!isPage) measureRoot()
            // The pointer in the window's space (the box's, for This frame).
            const qx = tx - ox
            const qy = ty - oy
            const s = settingsRef.current
            const dt = last ? Math.min(64, now - last) : 16.7
            last = now
            // A paused gap is capped at 64ms and is not a slow frame. Healthy frames are ~16ms.
